-- MFB CINEMA Supabase schema + curated catalogue seed. Apply in Supabase SQL Editor.
create extension if not exists pgcrypto;

create table if not exists public.movies (
  id bigint generated by default as identity primary key,
  title text not null check (char_length(title) between 1 and 180),
  year integer not null check (year between 1888 and 2100),
  genres text[] not null default array['Drama']::text[],
  image_url text not null default '',
  description text not null default '',
  runtime text not null default '',
  rating numeric(3,1) not null default 0 check (rating between 0 and 10),
  kind text not null default 'Film' check (kind in ('Film','Dizi')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists movies_rating_idx on public.movies (rating desc);
create index if not exists movies_year_idx on public.movies (year desc);
create index if not exists movies_genres_idx on public.movies using gin (genres);

create or replace function public.set_updated_at()
returns trigger language plpgsql set search_path = public
as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists movies_set_updated_at on public.movies;
create trigger movies_set_updated_at before update on public.movies
for each row execute function public.set_updated_at();

create table if not exists public.user_roles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check (role in ('admin','user')) default 'user',
  created_at timestamptz not null default now()
);

create table if not exists public.user_watch_history (
  user_id uuid not null references auth.users(id) on delete cascade,
  movie_id bigint not null references public.movies(id) on delete cascade,
  viewed_at timestamptz not null default now(),
  primary key (user_id, movie_id)
);
create index if not exists user_watch_history_user_viewed_idx on public.user_watch_history (user_id, viewed_at desc);

create table if not exists public.user_watchlist (
  user_id uuid not null references auth.users(id) on delete cascade,
  movie_id bigint not null references public.movies(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, movie_id)
);

-- User-submitted title ratings and reviews. Ratings are distinct from editorial catalogue scores.
create table if not exists public.movie_reviews (
  id uuid primary key default gen_random_uuid(),
  movie_id bigint not null references public.movies(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  display_name text not null default 'MFB member' check (char_length(display_name) between 1 and 100),
  rating integer not null check (rating between 1 and 5),
  comment text not null default '' check (char_length(comment) <= 600),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, movie_id)
);
create index if not exists movie_reviews_movie_created_idx on public.movie_reviews (movie_id, created_at desc);
create index if not exists movie_reviews_user_idx on public.movie_reviews (user_id);
drop trigger if exists movie_reviews_set_updated_at on public.movie_reviews;
create trigger movie_reviews_set_updated_at before update on public.movie_reviews
for each row execute function public.set_updated_at();

create or replace function public.is_mfb_admin()
returns boolean language sql stable security definer set search_path = public
as $$ select exists (select 1 from public.user_roles where user_id = auth.uid() and role = 'admin'); $$;
revoke all on function public.is_mfb_admin() from public;
grant execute on function public.is_mfb_admin() to anon, authenticated;

alter table public.movies enable row level security;
alter table public.user_roles enable row level security;
alter table public.user_watchlist enable row level security;
alter table public.user_watch_history enable row level security;
alter table public.movie_reviews enable row level security;

drop policy if exists "Catalogue is public to read" on public.movies;
create policy "Catalogue is public to read" on public.movies for select to anon, authenticated using (true);
drop policy if exists "Admins insert catalogue titles" on public.movies;
create policy "Admins insert catalogue titles" on public.movies for insert to authenticated with check (public.is_mfb_admin());
drop policy if exists "Admins update catalogue titles" on public.movies;
create policy "Admins update catalogue titles" on public.movies for update to authenticated using (public.is_mfb_admin()) with check (public.is_mfb_admin());
drop policy if exists "Admins delete catalogue titles" on public.movies;
create policy "Admins delete catalogue titles" on public.movies for delete to authenticated using (public.is_mfb_admin());

drop policy if exists "Users can read their own role" on public.user_roles;
create policy "Users can read their own role" on public.user_roles for select to authenticated using (user_id = auth.uid() or public.is_mfb_admin());
-- No client-side write policy for user_roles. Admins are promoted only through the SQL Editor.


drop policy if exists "Reviews are public to read" on public.movie_reviews;
create policy "Reviews are public to read" on public.movie_reviews for select to anon, authenticated using (true);
drop policy if exists "Users create own reviews" on public.movie_reviews;
create policy "Users create own reviews" on public.movie_reviews for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "Users update own reviews" on public.movie_reviews;
create policy "Users update own reviews" on public.movie_reviews for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists "Users delete own reviews" on public.movie_reviews;
create policy "Users delete own reviews" on public.movie_reviews for delete to authenticated using (user_id = auth.uid());

drop policy if exists "Users read own watchlist" on public.user_watchlist;
create policy "Users read own watchlist" on public.user_watchlist for select to authenticated using (user_id = auth.uid());
drop policy if exists "Users add to own watchlist" on public.user_watchlist;
create policy "Users add to own watchlist" on public.user_watchlist for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "Users remove from own watchlist" on public.user_watchlist;
create policy "Users remove from own watchlist" on public.user_watchlist for delete to authenticated using (user_id = auth.uid());

drop policy if exists "Users read own watch history" on public.user_watch_history;
create policy "Users read own watch history" on public.user_watch_history for select to authenticated using (user_id = auth.uid());
drop policy if exists "Users record own watch history" on public.user_watch_history;
create policy "Users record own watch history" on public.user_watch_history for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "Users update own watch history" on public.user_watch_history;
create policy "Users update own watch history" on public.user_watch_history for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists "Users clear own watch history" on public.user_watch_history;
create policy "Users clear own watch history" on public.user_watch_history for delete to authenticated using (user_id = auth.uid());

-- Public avatar URLs are readable; each user can only upload/change files inside their own folder.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 3145728, array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public = true, file_size_limit = 3145728, allowed_mime_types = array['image/jpeg','image/png','image/webp'];
drop policy if exists "Avatar images are public" on storage.objects;
create policy "Avatar images are public" on storage.objects for select using (bucket_id = 'avatars');
drop policy if exists "Users upload own avatar" on storage.objects;
create policy "Users upload own avatar" on storage.objects for insert to authenticated with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "Users update own avatar" on storage.objects;
create policy "Users update own avatar" on storage.objects for update to authenticated using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);
drop policy if exists "Users delete own avatar" on storage.objects;
create policy "Users delete own avatar" on storage.objects for delete to authenticated using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

