on conflict (id) do nothing;

-- Normalize known broken/placeholder image URLs to local fallbacks; preserve valid custom URLs.
update public.movies set image_url = '/posters/' || id::text || '.svg'
where image_url like 'https://placehold.co/%'
   or image_url like '%mfb-poster-fallback-%'
   or image_url like '%/posters/mfb-poster-fallback-%';
update public.movies set image_url = '/posters/59.svg' where id = 59 and image_url like '%vpbaStTMt8qq%';

select setval(pg_get_serial_sequence('public.movies','id'), greatest((select coalesce(max(id),1) from public.movies),1), true);

-- After registering and verifying your own account, promote it in the SQL Editor (replace the email):
-- insert into public.user_roles (user_id, role) select id, 'admin' from auth.users where email = 'YOUR_EMAIL@example.com' on conflict (user_id) do update set role = excluded.role;

-- Static editorial reference scores only; verify current IMDb values or use a licensed metadata provider before publication.


-- Public poster delivery with admin-only upload/update/delete. Re-runnable.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('posters', 'posters', true, 5242880, array['image/jpeg','image/png','image/webp','image/avif'])
on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists "Public can read poster objects" on storage.objects;
create policy "Public can read poster objects" on storage.objects for select to anon, authenticated using (bucket_id = 'posters');
drop policy if exists "Admins upload poster objects" on storage.objects;
create policy "Admins upload poster objects" on storage.objects for insert to authenticated with check (bucket_id = 'posters' and public.is_mfb_admin());
drop policy if exists "Admins update poster objects" on storage.objects;
create policy "Admins update poster objects" on storage.objects for update to authenticated using (bucket_id = 'posters' and public.is_mfb_admin()) with check (bucket_id = 'posters' and public.is_mfb_admin());
drop policy if exists "Admins delete poster objects" on storage.objects;
create policy "Admins delete poster objects" on storage.objects for delete to authenticated using (bucket_id = 'posters' and public.is_mfb_admin());

-- Extended catalogue metadata and account features. This block is additive and safe to rerun.
alter table public.movies add column if not exists backdrop_url text not null default '';
alter table public.movies add column if not exists director text not null default '';
alter table public.movies add column if not exists cast_names text not null default '';
alter table public.movies add column if not exists language text not null default '';
alter table public.movies add column if not exists country text not null default '';
alter table public.movies add column if not exists popularity integer not null default 0 check (popularity >= 0);
alter table public.movies add column if not exists is_featured boolean not null default false;
alter table public.movies add column if not exists is_published boolean not null default true;
create index if not exists movies_published_popularity_idx on public.movies (is_published, popularity desc);

create table if not exists public.user_favorites (
  user_id uuid not null references auth.users(id) on delete cascade,
  movie_id bigint not null references public.movies(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, movie_id)
);
create index if not exists user_favorites_user_created_idx on public.user_favorites (user_id, created_at desc);
alter table public.user_favorites enable row level security;
drop policy if exists "Users read own favorites" on public.user_favorites;
create policy "Users read own favorites" on public.user_favorites for select to authenticated using (user_id = auth.uid());
drop policy if exists "Users add own favorites" on public.user_favorites;
create policy "Users add own favorites" on public.user_favorites for insert to authenticated with check (user_id = auth.uid());
drop policy if exists "Users remove own favorites" on public.user_favorites;
create policy "Users remove own favorites" on public.user_favorites for delete to authenticated using (user_id = auth.uid());

create table if not exists public.seasons (
  id bigint generated by default as identity primary key,
  series_id bigint not null references public.movies(id) on delete cascade,
  season_number integer not null check (season_number > 0),
  title text not null default '',
  poster_url text not null default '',
  release_date date,
  unique (series_id, season_number)
);
create table if not exists public.episodes (
  id bigint generated by default as identity primary key,
  season_id bigint not null references public.seasons(id) on delete cascade,
  episode_number integer not null check (episode_number > 0),
  title text not null check (char_length(title) between 1 and 180),
  synopsis text not null default '',
  runtime_minutes integer check (runtime_minutes is null or runtime_minutes > 0),
  still_url text not null default '',
  air_date date,
  unique (season_id, episode_number)
);
create index if not exists seasons_series_order_idx on public.seasons (series_id, season_number);
create index if not exists episodes_season_order_idx on public.episodes (season_id, episode_number);
alter table public.seasons enable row level security;
alter table public.episodes enable row level security;
drop policy if exists "Published seasons are public to read" on public.seasons;
create policy "Published seasons are public to read" on public.seasons for select to anon, authenticated using (exists (select 1 from public.movies m where m.id = series_id and m.is_published and m.kind = 'Dizi'));
drop policy if exists "Admins manage seasons" on public.seasons;
create policy "Admins manage seasons" on public.seasons for all to authenticated using (public.is_mfb_admin()) with check (public.is_mfb_admin());
drop policy if exists "Published episodes are public to read" on public.episodes;
create policy "Published episodes are public to read" on public.episodes for select to anon, authenticated using (exists (select 1 from public.seasons s join public.movies m on m.id = s.series_id where s.id = season_id and m.is_published and m.kind = 'Dizi'));
drop policy if exists "Admins manage episodes" on public.episodes;
create policy "Admins manage episodes" on public.episodes for all to authenticated using (public.is_mfb_admin()) with check (public.is_mfb_admin());

create table if not exists public.cast_members (
  id bigint generated by default as identity primary key,
  name text not null check (char_length(name) between 1 and 180),
  profile_url text not null default '',
  biography text not null default ''
);
create table if not exists public.content_cast_members (
  movie_id bigint not null references public.movies(id) on delete cascade,
  cast_member_id bigint not null references public.cast_members(id) on delete cascade,
  character_name text not null default '',
  credit_order integer not null default 0,
  primary key (movie_id, cast_member_id)
);
create index if not exists content_cast_order_idx on public.content_cast_members (movie_id, credit_order);
alter table public.cast_members enable row level security;
alter table public.content_cast_members enable row level security;
drop policy if exists "Cast is public to read" on public.cast_members;
create policy "Cast is public to read" on public.cast_members for select to anon, authenticated using (true);
drop policy if exists "Admins manage cast" on public.cast_members;
create policy "Admins manage cast" on public.cast_members for all to authenticated using (public.is_mfb_admin()) with check (public.is_mfb_admin());
drop policy if exists "Content credits are public to read" on public.content_cast_members;
create policy "Content credits are public to read" on public.content_cast_members for select to anon, authenticated using (exists (select 1 from public.movies m where m.id = movie_id and m.is_published));
drop policy if exists "Admins manage content credits" on public.content_cast_members;
create policy "Admins manage content credits" on public.content_cast_members for all to authenticated using (public.is_mfb_admin()) with check (public.is_mfb_admin());

create table if not exists public.user_notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  notification_type text not null default 'system',
  title text not null check (char_length(title) between 1 and 180),
  message text not null default '',
  payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  read_at timestamptz
);
create index if not exists user_notifications_user_created_idx on public.user_notifications (user_id, created_at desc);
alter table public.user_notifications enable row level security;
drop policy if exists "Users read own notifications" on public.user_notifications;
create policy "Users read own notifications" on public.user_notifications for select to authenticated using (user_id = auth.uid());
drop policy if exists "Users mark own notifications read" on public.user_notifications;
create policy "Users update own notifications read state" on public.user_notifications for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
-- Intentionally no client insert/delete policy: trusted server-side workflows create notifications.
revoke update on table public.user_notifications from authenticated;
grant update (read_at) on table public.user_notifications to authenticated;

create table if not exists public.watch_party_rooms (
  id uuid primary key default gen_random_uuid(),
  room_code text not null unique check (room_code ~ '^[A-Z0-9]{6,12}$'),
  host_user_id uuid not null references auth.users(id) on delete cascade,
  movie_id bigint not null references public.movies(id) on delete cascade,
  is_active boolean not null default true,
  is_playing boolean not null default false,
  position_seconds double precision not null default 0 check (position_seconds >= 0),
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);
create table if not exists public.watch_party_participants (
  room_id uuid not null references public.watch_party_rooms(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  joined_at timestamptz not null default now(),
  primary key (room_id, user_id)
);
create index if not exists watch_party_active_idx on public.watch_party_rooms (is_active, created_at desc);
alter table public.watch_party_rooms enable row level security;
alter table public.watch_party_participants enable row level security;
drop policy if exists "Participants can read joined rooms" on public.watch_party_rooms;
create policy "Participants can read joined rooms" on public.watch_party_rooms for select to authenticated using (host_user_id = auth.uid() or exists (select 1 from public.watch_party_participants p where p.room_id = id and p.user_id = auth.uid()));
drop policy if exists "Users create own watch parties" on public.watch_party_rooms;
create policy "Users create own watch parties" on public.watch_party_rooms for insert to authenticated with check (host_user_id = auth.uid());
drop policy if exists "Hosts manage own watch parties" on public.watch_party_rooms;
create policy "Hosts manage own watch parties" on public.watch_party_rooms for update to authenticated using (host_user_id = auth.uid()) with check (host_user_id = auth.uid());
drop policy if exists "Participants read own participation" on public.watch_party_participants;
create policy "Participants read own participation" on public.watch_party_participants for select to authenticated using (user_id = auth.uid() or exists (select 1 from public.watch_party_rooms r where r.id = room_id and r.host_user_id = auth.uid()));
-- Participant inserts are server-controlled so invite-code validation cannot be bypassed through the client.

-- SECURITY DEFINER helper avoids recursive RLS evaluation between rooms and participants.
create or replace function public.is_watch_party_participant(target_room_id uuid)
returns boolean language sql stable security definer set search_path = public
as $$ select exists (select 1 from public.watch_party_participants p where p.room_id = target_room_id and p.user_id = auth.uid()); $$;
revoke all on function public.is_watch_party_participant(uuid) from public;
grant execute on function public.is_watch_party_participant(uuid) to authenticated;
drop policy if exists "Participants can read joined rooms" on public.watch_party_rooms;
create policy "Participants can read joined rooms" on public.watch_party_rooms for select to authenticated using (host_user_id = auth.uid() or public.is_watch_party_participant(id));
drop policy if exists "Participants read own participation" on public.watch_party_participants;
create policy "Participants read own participation" on public.watch_party_participants for select to authenticated using (user_id = auth.uid() or exists (select 1 from public.watch_party_rooms r where r.id = room_id and r.host_user_id = auth.uid()));
